 "content": "from math import gcd
from functools import reduce

def transform(grid):
    g = [row[:] for row in grid]
    h, w = len(g), len(g[0])
    gray = [(r, c) for r in range(h) for c in range(w) if g[r][c] == 8]
    key = [(r, c) for r in range(h) for c in range(w) if g[r][c] not in (0, 8)]
    if not gray or not key:
        return g

    # The small multicolored pattern is the color key; the gray silhouette
    # is the same pattern rotated clockwise, with each cell enlarged uniformly.
    kr0, kr1 = min(r for r, c in key), max(r for r, c in key)
    kc0, kc1 = min(c for r, c in key), max(c for r, c in key)
    key_grid = [row[kc0:kc1 + 1] for row in g[kr0:kr1 + 1]]
    rotated = [list(row) for row in zip(*key_grid[::-1])]

    r0, r1 = min(r for r, c in gray), max(r for r, c in gray)
    c0, c1 = min(c for r, c in gray), max(c for r, c in gray)
    runs = []
    for r in range(r0, r1 + 1):
        c = c0
        while c <= c1:
            if g[r][c] == 8:
                s = c
                while c <= c1 and g[r][c] == 8:
                    c += 1
                runs.append(c - s)
            else:
                c += 1
    for c in range(c0, c1 + 1):
        r = r0
        while r <= r1:
            if g[r][c] == 8:
                s = r
                while r <= r1 and g[r][c] == 8:
                    r += 1
                runs.append(r - s)
            else:
                r += 1
    scale = reduce(gcd, runs)
    nr, nc = len(rotated), len(rotated[0])
    for br in range(nr):
        for bc in range(nc):
            color = rotated[br][bc]
            if color and all(g[r][c] == 8
                             for r in range(r0 + br * scale, r0 + (br + 1) * scale)
                             for c in range(c0 + bc * scale, c0 + (bc + 1) * scale)):
                for r in range(r0 + br * scale, r0 + (br + 1) * scale):
                    for c in range(c0 + bc * scale, c0 + (bc + 1) * scale):
                        g[r][c] = color
    return g
